) values
(
  'delivery-intelligence-the-sleep-company',
  'Delivery Intelligence | The Sleep Company',
  'https://thesleepcompany.in',
  'Ecommerce - Backend Architecture - Production Systems',
  'Delivery promises made dependable',
  $$A large ecommerce business needed one reliable source of truth for delivery estimates across products, warehouses, locations, couriers, holidays, manufacturing delays, stock status, and express-delivery rules.$$,
  $$A centralized delivery-estimation service combined operational data and business rules from courier, inventory, ecommerce, and warehouse systems, with caching, administrative data controls, version history, backup and restore, and automated alerts.$$,
  array[
    'Backend architecture',
    'API design',
    'Business-rule modelling',
    'External integrations',
    'Caching',
    'Production scaling',
    'Observability',
    'Long-term maintenance'
  ],
  '[{"value":"50%","label":"reduction in support calls"},{"value":"5x","label":"FRT improvement"},{"value":"₹5 crore","label":"annual cost savings"}]'::jsonb,
  true,
  $case_study{"role":"Backend lead: Architecture, API design, integrations, infrastructure, production support, complete technical ownership.","summary":"A scattered delivery-date calculation process was rebuilt as a centralized EDD service that could support ecommerce touchpoints, logistics operations, warehouse data, product rules, courier timelines, stock states, holidays, and manufacturing delays from one dependable source of truth.","sections":[{"id":"outcome-snapshot","rows":[{"after":"95%","before":"30%","impact":"~2x accuracy increase","metric":"Delivery-date accuracy"},{"after":"250","before":"500","impact":"50% reduction","metric":"Daily support calls"},{"after":"60%","before":"10%","impact":"5x improvement","metric":"FRT"}],"tone":"muted","type":"outcome-table","title":"Delivery accuracy, support load, and response speed moved together.","footer":{"label":"annual cost savings","value":"₹5 crore","detail":"Lower support volume and faster first-response handling turned the operational gains into measurable recurring savings."},"eyebrow":"Outcome snapshot"},{"id":"operating-model-shift","tone":"base","type":"comparison","items":[{"after":"One backend EDD API serving ecommerce, logistics, warehouse, and operational touchpoints.","before":"Delivery estimates split across frontend logic, team-owned sheets, and disconnected databases."},{"after":"A single calculation path combined product, courier, warehouse, order, holiday, stock, and cutoff data.","before":"Important variables handled inconsistently: stock state, holidays, manufacturing delay, courier timing, and warehouse location."},{"after":"Controlled upload workflows, validation reports, snapshots, restores, and alerts gave operations a safer way to manage EDD data.","before":"Manual correction loops created support pressure and low confidence in customer-facing promises."}],"title":"From fragmented delivery promises to one controlled source of truth.","eyebrow":"Operating model shift","afterLabel":"After","beforeLabel":"Before"},{"id":"system-flow","tone":"muted","type":"system-flow","items":[{"stat":"8","step":"01","title":"Normalize scattered inputs","detail":"Product, warehouse, courier, order, holiday, stock, and manufacturing-delay data were brought into one calculation path.","statLabel":"data domains"},{"stat":"7","step":"02","title":"Control operational changes","detail":"Admin updates moved through validation, correction sheets, snapshots, restores, and cache refreshes before affecting live promises.","statLabel":"control workflows"},{"stat":"3","step":"03","title":"Serve one EDD API","detail":"A NestJS service read operational records from MongoDB and served high-read delivery rules through Redis-backed paths.","statLabel":"runtime layers"}],"title":"Scattered delivery data became one controlled delivery-date API.","eyebrow":"System flow"},{"id":"operational-control","tone":"base","type":"workflow","cards":[{"title":"Validated uploads","detail":"CSV/XLSX files were checked row by row before operational data could replace active collections.","keywords":["CSV/XLSX","row-level errors","admin workflow"]},{"title":"Snapshot-backed restores","detail":"Every upload and restore preserved the current collection first, keeping rollback paths available.","keywords":["snapshot","restore","MongoDB"]},{"title":"Operational alerts","detail":"Kubernetes-backed checks surfaced variant stock changes and admin-dashboard alerts.","keywords":["cron checks","stock state","alerts"]}],"intro":"Operations could update the rules behind customer-facing promises without scattered sheets, unsafe replacements, or unclear failures.","steps":["Upload","Validate","Correction sheet","Snapshot","Replace","Refresh cache","Alert"],"title":"Data changes became validated, reversible, and cache-aware.","eyebrow":"Operational control"},{"id":"engineering-decisions","tone":"muted","type":"evidence-grid","cards":[{"title":"Isolated EDD service","detail":"Delivery logic could evolve in one backend system instead of being duplicated across touchpoints.","keywords":["NestJS","single API","service boundary"]},{"title":"Redis-backed read path","detail":"High-read rules such as holidays, processing times, cutoff hours, and variant delays were cached and refreshed after database changes.","keywords":["Redis","cache refresh","high-read data"]},{"title":"Lifecycle-aware delay logic","detail":"Holiday and Sunday handling accounted for where delay happened: factory, warehouse, courier, or post-dispatch.","keywords":["holidays","cutoffs","delay rules"]},{"title":"Seasonal traffic headroom","detail":"The deployment was designed to handle seasonal bursts without losing the central EDD dependency.","keywords":["Kubernetes","Diwali","scaling"]}],"title":"Choices shaped around central dependency risk and production traffic.","eyebrow":"Engineering decisions"},{"id":"production-proof","tone":"base","type":"evidence-grid","cards":[{"title":"Seasonal traffic headroom","detail":"The central EDD service stayed dependable during Diwali demand, supporting 1.45M period requests and traffic roughly 199% above the previous month.","keywords":["1.45M requests","199% traffic lift","Kubernetes scaling"]},{"title":"Cache-safe rule updates","detail":"High-read delivery rules were served through Redis and refreshed after database changes, so admin updates did not leave stale promises in circulation.","keywords":["Redis","cache refresh","high-read rules"]},{"title":"Rollback-ready operations","detail":"Uploads validated rows before replacement and snapshotted active collections first, giving operations a controlled recovery path for delivery data changes.","keywords":["row validation","snapshots","restore path"]},{"title":"Production visibility","detail":"SigNoz brought EDD logs and traces into one searchable view, with alerts surfacing downtime, slow P90 responses, and elevated error rates before delivery promises degraded.","keywords":["SigNoz","P90 monitoring","error alerts"]}],"title":"The system held up where production systems usually break.","eyebrow":"Production proof","circuitAnchor":"section-bottom"},{"id":"communication-automation","tone":"base","type":"impact-highlight","title":"Customer communication rebuilt around the full order journey.","detail":"A separate notification-system overhaul was built to keep customers properly informed throughout the entire order journey—from order placement through processing, dispatch, delivery, cancellation, and returns. The system relied heavily on EDD as the foundation for timely, journey-aware communication.","eyebrow":"Additional impact","metrics":[{"label":"reduction in support calls","value":"35%"},{"label":"annual support-cost savings","value":"₹3 crore"},{"label":"new notifications introduced","value":"30+"}],"capabilities":["Notification-system architecture","Order-journey communication","Event integrations","Technical ownership"],"circuitAnchor":"section-bottom","circuitImpactPalette":"dark-blue-pink"},{"id":"capabilities-demonstrated","tone":"muted","type":"capability-band","title":"Backend architecture carried through production ownership.","eyebrow":"Capabilities demonstrated","primaryActionLabel":"Discuss a Project","secondaryActionLabel":"Visit Live Site","showProjectCapabilities":true}],"background":{"type":"pcb-svg","bucket":"case-study-assets","objectPath":"delivery-intelligence-the-sleep-company/background.fff5c7fbe538eabf7bff.svg","lensObjectPath":"delivery-intelligence-the-sleep-company/background-lens.ed3d7b911febb7a95ba3.svg","width":2400,"height":15183.5},"heroVisual":{"type":"edd-calculation","title":"One request, resolved into a dependable promise.","layout":{"canvas":{"width":1440,"height":810,"gridSize":28,"frameInset":1},"mobile":{"stageGap":26,"groupLabel":"Promise engine","connections":[{"to":"engine","from":"request","kind":"primary"},{"to":"engine","from":"clickpost","kind":"api"},{"to":"engine","from":"easyecom","kind":"api"},{"to":"response","from":"engine","kind":"primary"}],"entryColumns":[37.5,25,37.5],"stageColumns":{"gap":22,"compactGap":16,"titleFraction":0.55,"titleMinWidth":108,"detailsFraction":1.45},"stagePadding":20,"canvasPadding":32,"enginePadding":20,"endpointPadding":22,"entryPaddingTop":28,"compactFieldRows":{"gap":12,"paddingBlock":13,"labelFraction":0.42,"labelMinWidth":82,"valueFraction":1},"entryPaddingBottom":38,"integrationPadding":12,"compactStagePadding":18,"compactCanvasPadding":18,"compactEnginePadding":18,"integrationPositions":[{"column":1,"integrationKey":"clickpost"},{"column":3,"integrationKey":"easyecom"}],"compactEndpointPadding":18,"integrationConnectorGap":4,"responseConnectorHeight":34,"compactIntegrationPadding":10,"compactStageHeaderPadding":15,"integrationConnectorHeight":36},"tablet":{"request":{"x":24,"y":260,"width":202,"height":280},"boundary":{"x":316,"y":130,"width":808,"height":535},"response":{"x":1214,"y":260,"width":202,"height":280},"services":[{"x":888,"y":25,"path":"M888 60 C844 60 800 80 800 118","width":224,"height":70,"integrationKey":"clickpost"},{"x":316,"y":715,"path":"M540 750 C590 750 650 720 650 677","width":224,"height":70,"integrationKey":"easyecom"}],"flowPaths":["M238 400 C260 400 282 400 304 400","M461 377 V423 C461 452 482 475 508 475","M634 418 V372 C634 343 655 325 681 325","M807 377 V423 C807 452 828 475 854 475","M1136 400 C1158 400 1180 400 1202 400"],"stageSize":{"width":236,"height":185},"stagePositions":[{"x":347,"y":180},{"x":520,"y":430},{"x":693,"y":180},{"x":866,"y":430}]},"desktop":{"request":{"x":24,"y":260,"width":190,"height":280},"boundary":{"x":320,"y":130,"width":800,"height":535},"response":{"x":1226,"y":260,"width":190,"height":280},"services":[{"x":900,"y":25,"path":"M900 60 C850 60 800 80 800 118","width":200,"height":70,"integrationKey":"clickpost"},{"x":340,"y":715,"path":"M540 750 C590 750 650 720 650 677","width":200,"height":70,"integrationKey":"easyecom"}],"flowPaths":["M226 400 C254 400 280 400 308 400","M461 377 V423 C461 452 482 475 502 475 H514","M634 418 V372 C634 343 655 325 675 325 H687","M807 377 V423 C807 452 828 475 848 475 H860","M1132 400 C1160 400 1186 400 1214 400"],"stageSize":{"width":216,"height":185},"stagePositions":[{"x":353,"y":180},{"x":526,"y":430},{"x":699,"y":180},{"x":872,"y":430}]},"breakpoints":{"mobileMax":800,"tabletMax":1080,"compactMax":480}},"stages":[{"items":[{"label":"Pincode serviceability"},{"label":"Recommended courier partner","sourceKey":"clickpost"},{"label":"Available delivery modes"}],"title":"Destination resolution","number":"01"},{"items":[{"label":"Inventory availability"},{"label":"Warehouse determination","sourceKey":"easyecom"},{"label":"Warehouse details","sourceKey":"easyecom"}],"title":"Fulfilment source","number":"02"},{"items":[{"label":"Processing time"},{"label":"Manufacturing delay"},{"label":"Cutoff + holiday calendar"}],"title":"Dispatch readiness","number":"03"},{"items":[{"label":"Baseline post-dispatch range","sourceKey":"clickpost"},{"label":"Express eligibility","sourceKey":"clickpost"},{"label":"Final delivery range"}],"title":"Promise assembly","number":"04"}],"eyebrow":"Request to promise","description":"A delivery estimate request follows a curved path through destination resolution, fulfilment source, dispatch readiness, and promise assembly. EasyEcom supplies warehouse data. ClickPost supplies courier and delivery-promise data before the service returns dispatch, delivery-range, and express-availability values.","integrations":[{"key":"clickpost","name":"ClickPost","role":"Courier API"},{"key":"easyecom","name":"EasyEcom","role":"Warehouse API"}],"requestLabel":"EDD request","requestFields":[{"label":"Product","value":"Product ID"},{"label":"Destination","value":"Pincode"},{"label":"Requested","value":"Date + time"}],"responseLabel":"EDD response","responseFields":[{"label":"Dispatch","value":"Dispatch date"},{"label":"Delivery","value":"Date range"},{"label":"Express","value":"Available / unavailable"}]},"schemaVersion":3}$case_study$::jsonb,
