  'published'
),
(
  'leads-management-the-sleep-company',
  'Leads Management | The Sleep Company',
  'https://thesleepcompany.in',
  'Ecommerce - Integrations - High-Volume Systems',
  'Fragmented lead capture, rebuilt as one dependable system',
  $$Lead capture relied on spreadsheets and disconnected systems. The business needed a centralized platform for collecting lead activities, retaining owned records, enriching applicable data, and synchronizing it across marketing, sales, and analytics systems.$$,
  $$A centralized lead service replaced spreadsheet-based middleware, retained owned lead-activity records, normalized payloads for downstream systems, enriched applicable activities through a nearest-store API, and handled custom activity-type workflows.$$,
  array[
    'System integration',
    'Backend architecture',
    'Business workflows',
    'Data enrichment',
    'Workflow orchestration',
    'Cloud deployment',
    'Scaling',
    'Production support'
  ],
  '[{"value":"2.2x","label":"daily activity volume growth"},{"value":"626K","label":"monthly activities sustained"},{"value":"3.6M","label":"requests in 30 days"}]'::jsonb,
  true,
  $case_study{"role":"Backend lead: Architecture, API design, integrations, infrastructure, production support, complete technical ownership.","summary":"80+ website and store-management touchpoints depended on Google Sheets workflows that dropped over half of incoming lead activities. One owned lead service replaced that fragile handoff with consistent processing, durable activity records, custom activity-type workflows, downstream synchronization, and production recovery.","sections":[{"id":"outcome-snapshot","rows":[{"after":"~99.5%","before":"Less than 50%","impact":"Nearly complete capture","metric":"Lead-activity capture"},{"after":"410,087 · Jan 2025","before":"177,080 · Nov 2024","impact":"~2.2x daily activity volume","metric":"Monthly lead activities"},{"after":"Owned records + analytics","before":"Manual reconciliation","impact":"Almost all gathering work removed","metric":"Lead-activity data operations"}],"tone":"muted","type":"outcome-table","title":"Lead-activity capture became dependable enough to support business growth.","footer":{"label":"of revenue influenced by lead journeys","value":"≈70%","detail":"Dependable capture protected a commercially important acquisition channel instead of leaving it constrained by spreadsheet throughput."},"eyebrow":"Outcome snapshot"},{"id":"operating-model-shift","tone":"base","type":"comparison","items":[{"after":"One NestJS service received lead activities from website, store, and webhook touchpoints.","before":"Google Sheets workflows dropped more than half of incoming lead activities under production volume."},{"after":"MongoDB retained activity payloads and downstream processing states in one controlled record.","before":"The business had no owned lead-activity database and depended on downstream tools for visibility."},{"after":"LeadSquared, WebEngage, and BigQuery received data through one observable workflow.","before":"Analytics and propagation required manual searching across disconnected sources."}],"title":"From spreadsheet transport to owned lead infrastructure.","eyebrow":"Operating model shift","afterLabel":"After","beforeLabel":"Before"},{"id":"system-flow","tone":"muted","type":"system-flow","items":[{"stat":"2","step":"01","title":"Accept valuable data","detail":"Loose validation preserved incomplete lead activities instead of rejecting them before the business could act.","statLabel":"required fields"},{"stat":"80+","step":"02","title":"Normalize by type","detail":"Shared mappings handled the common path while custom activities and source payloads used bounded type-specific processing.","statLabel":"touchpoints"},{"stat":"3","step":"03","title":"Persist and distribute","detail":"The owned activity record kept the source payload and task states before data moved into sales, engagement, and analytics systems.","statLabel":"downstream systems"}],"title":"Every lead activity entered one owned processing path.","eyebrow":"System flow"},{"id":"workflow-control","tone":"base","type":"workflow","cards":[{"title":"Separate task states","detail":"LeadSquared, WebEngage, BigQuery, and other tasks retained independent success or failure fields.","keywords":["targeted recovery","task status","owned record"]},{"title":"Three-day retry window","detail":"A daily Kubernetes cron inspected recent records and repeated only the downstream work that remained incomplete.","keywords":["daily cron","bounded replay","failure recovery"]},{"title":"Operational visibility","detail":"Teams could inspect central records and analytics directly while routine recovery stayed automated.","keywords":["MongoDB","BigQuery","less manual work"]}],"intro":"Separate task states and a bounded retry window turned partial downstream failures into routine recovery work instead of silently lost lead activities.","steps":["Receive","Validate essentials","Map + enrich","Persist","Propagate","Record status","Retry failures"],"title":"Failed downstream work remained visible and recoverable.","eyebrow":"Workflow control"},{"id":"engineering-decisions","tone":"muted","type":"evidence-grid","cards":[{"title":"Preserve first","detail":"MongoDB retained structured and loosely structured fields so newly introduced payload data was not discarded while mappings evolved.","keywords":["MongoDB","evolving payloads","field retention"]},{"title":"Permissive validation","detail":"Only phone number and activity type were mandatory because incomplete activity data could still have commercial value.","keywords":["business value","loose schema","capture first"]},{"title":"Custom type workflows","detail":"Common lead activities reused one mapping path; LeadSquared custom activities and source exceptions used explicit type-based processing.","keywords":["shared mapping","custom activities","bounded exceptions"]},{"title":"Open, rate-limited API","detail":"The ingestion boundary stayed open for distributed business touchpoints while IP-based limits constrained abuse.","keywords":["IP rate limits","open ingestion","touchpoint access"]}],"title":"The architecture protected capture without overengineering the first release.","eyebrow":"Engineering decisions"},{"id":"production-proof","tone":"base","type":"evidence-grid","cards":[{"title":"626,470 lead activities","detail":"The owned service sustained more than 626K lead-activity records in a measured 30-day period.","keywords":["30 days","owned records","production scale"]},{"title":"3,611,900 requests","detail":"Webhook-heavy traffic was sustained in the same period; repeated LeadSquared activity callbacks accounted for most requests.","keywords":["webhook traffic","contextual metric","LeadSquared"]},{"title":"Scaling assumptions corrected","detail":"A 75% trigger and 60-second scale-down window caused spike intolerance. The policy moved to 60% CPU with a 300-second stabilization window.","keywords":["2–10 pods","60% CPU","300s stabilization"]},{"title":"Observable by design","detail":"SigNoz exposed searchable logs and traces with alerts for downtime, P90 degradation, elevated 500s, and elevated 400s.","keywords":["SigNoz","P90","logs + traces"]}],"title":"The system handled sales traffic—and improved when an assumption failed.","eyebrow":"Production proof","circuitAnchor":"section-bottom"},{"id":"capabilities-demonstrated","tone":"muted","type":"capability-band","title":"Lead infrastructure carried through production ownership.","eyebrow":"Capabilities demonstrated","primaryActionLabel":"Discuss a Project","secondaryActionLabel":"Visit Live Site","showProjectCapabilities":true}],"background":{"type":"pcb-svg","bucket":"case-study-assets","objectPath":"leads-management-the-sleep-company/background.0de4c8bc000082604a62.svg","lensObjectPath":"leads-management-the-sleep-company/background-lens.85f40a3149ed04d5f1c7.svg","width":2400,"height":14173.8},"heroVisual":{"type":"lead-network","title":"Many lead-activity sources, one controlled processing path.","layout":{"wide":{"core":{"x":395,"y":26,"width":450,"height":568},"statY":84,"titleY":45,"nodeGap":93,"sourceX":26,"laneWidth":284,"nodeTextX":17,"nodeWidth":284,"nodeHeight":79,"nodeStartY":178,"nodeTitleY":32,"nodeDetailY":57,"sourceRuleY":100,"destinationX":930,"nodeAccentEndX":40,"destinationRuleY":64,"nodeAccentStartX":16,"sourceConnectorPath":"M322 310H383","destinationConnectorPath":"M857 310H918"},"canvas":{"width":1240,"height":620,"gridSize":28,"frameInset":1},"breakpoints":{"mobileMax":800,"tabletMax":1080,"compactMax":650}},"record":{"name":"MongoDB","role":"Owned database","detail":"Source activity + downstream task states"},"stages":[{"title":"Capture","detail":"Phone + activity type","number":"01"},{"title":"Normalize","detail":"Shared field mapping","number":"02"},{"title":"Enrich","detail":"Nearest-store lookup","number":"03"},{"title":"Process","detail":"Custom activity workflows","number":"04"}],"eyebrow":"Touchpoint to owned record","sources":[{"key":"website","name":"Website journeys","role":"Forms + product flows"},{"key":"stores","name":"Store platforms","role":"Assisted activity capture"},{"key":"webhooks","name":"Inbound webhooks","role":"JustDial + LeadSquared"}],"sourceStat":"80+","description":"Website, store, and webhook activity converges into one Lead Service before owned storage and downstream delivery.","serviceRole":"Owned processing boundary","sourceLabel":"Capture surface","destinations":[{"key":"leadsquared","name":"LeadSquared","role":"CRM + activities"},{"key":"webengage","name":"WebEngage","role":"Customer engagement"},{"key":"bigquery","name":"BigQuery","role":"Lead analytics"}],"serviceLabel":"Lead Service","sourceStatLabel":"touchpoints","destinationLabel":"Downstream systems"},"schemaVersion":3}$case_study$::jsonb,
  2,
  'published'
),
(
  'horecah',
  'Horecah',
  '',
  'Freelance - Cross-Platform - Payments and Notifications',
  'Payments and notification journeys across web, Android, and iOS',
  $$A new hospitality hiring product needed two release-critical capabilities to behave consistently across three client platforms.$$,
  $$End-to-end Razorpay payments and event-driven push notifications were delivered through one React and Capacitor application, including backend verification, platform delivery, and deep-link routing.$$,
  array[
    'Cross-platform feature delivery',
    'Payment integration',
    'Push notifications',
    'Backend APIs',
    'Hasura events',
    'Deep linking',
    'Third-party package adaptation',
    'Production testing'
  ],
  '[{"value":"1","label":"shared client"},{"value":"2","label":"production features"},{"value":"3","label":"client platforms"}]'::jsonb,
  true,
  $case_study{"role":"Freelance feature engineer: End-to-end ownership of Razorpay payments and push notifications across web, Android, and iOS.","summary":"Horecah's first release needed payments and transactional notifications to work as complete product journeys across web, Android, and iOS. During a one-month freelance engagement, both capabilities were delivered end to end through the shared React and Capacitor application, its Node.js backend, and Hasura-backed PostgreSQL data layer.","sections":[{"id":"feature-scope","tone":"muted","type":"evidence-grid","cards":[{"title":"Shared client foundation","detail":"One React and Capacitor application carried the common client contracts and platform configuration across web, Android, and iOS.","keywords":["React + Capacitor","web + native","one client"]},{"title":"Payments, end to end","detail":"Ownership ran from backend order creation and Razorpay checkout through signature verification and independent webhook reconciliation.","keywords":["order creation","checkout","verification"]},{"title":"Notifications, event to destination","detail":"Ownership ran from Hasura-triggered product events through FCM or APNs delivery and destination-aware navigation after a tap.","keywords":["Hasura events","FCM + APNs","deep linking"]}],"title":"Two production features, delivered through one shared cross-platform client.","columns":3,"eyebrow":"Feature scope"},{"id":"payment-integration","tone":"base","type":"evidence-grid","cards":[{"title":"Production-ready Capacitor fork","detail":"Razorpay's official Capacitor plugin did not integrate cleanly with the production setup. Its TypeScript toolchain, bundle format, checkout types, package identity, distributable build, and CocoaPods identity were adapted in a maintained Horecah fork.","keywords":["Capacitor 6","TypeScript","CocoaPods"]},{"title":"One implementation across clients","detail":"The repaired package kept web and native checkout behind one application-level contract instead of creating separate payment implementations for each platform.","keywords":["shared contract","web + native","Razorpay"]},{"title":"Two failure boundaries","detail":"Checkout responses were verified on the backend for immediate completion, while server-to-server webhooks reconciled payment state independently of the active client.","keywords":["signature verification","webhooks","reconciliation"]}],"title":"The shared payment flow required repairing the plugin boundary.","eyebrow":"Payment integration"},{"id":"notification-delivery","tone":"muted","type":"evidence-grid","cards":[{"title":"Event-driven delivery","detail":"Hasura events connected product activity to automatic notification journeys instead of requiring manual sends.","keywords":["Hasura events","automatic triggers","PostgreSQL"]},{"title":"Platform-aware routing","detail":"The backend stored device tokens and selected FCM or APNs delivery according to the registered client platform.","keywords":["device tokens","FCM","APNs"]},{"title":"Consistent deep links","detail":"A shared payload structure carried the destination data needed for notification taps to open the intended React screen consistently on web, Android, and iOS.","keywords":["payload contract","deep links","cross-platform"]},{"title":"Web push restored","detail":"An initial web-push integration failure was diagnosed and resolved as part of bringing the complete notification path to release readiness.","keywords":["web push","integration debugging","release path"]}],"title":"A notification only worked when it returned the user to the right journey.","eyebrow":"Notification delivery"},{"id":"production-readiness","tone":"base","type":"evidence-grid","cards":[{"title":"Real-platform verification","detail":"Payments and notifications were exercised in web browsers and on physical Android and iOS devices, including foreground, background, and terminated application states.","keywords":["real devices","browser checks","app lifecycle"]},{"title":"Failure paths covered","detail":"Cancelled and failed payments, invalid verification, expired device tokens, and unsuccessful notification delivery were handled as part of the feature boundary.","keywords":["error handling","token lifecycle","payment failures"]},{"title":"Production v1 launch","detail":"The payment gateway and automated notification journeys launched with the complete first version of the product.","keywords":["v1 launch","payments","production ready"]}],"title":"Both features shipped with Horecah's first production release.","eyebrow":"Production readiness","circuitAnchor":"section-bottom"},{"id":"capabilities-demonstrated","tone":"muted","type":"capability-band","title":"Cross-platform features carried through their complete production boundary.","eyebrow":"Capabilities demonstrated","primaryActionLabel":"Discuss a Project","secondaryActionLabel":"Visit Live Site","showProjectCapabilities":true}],"background":{"type":"pcb-svg","bucket":"case-study-assets","objectPath":"horecah/background.8812277dcb9def6845a9.svg","lensObjectPath":"horecah/background-lens.63804fd846af2ecceab8.svg","width":2400,"height":11019.3},"heroVisual":{"type":"cross-platform-features","title":"One shared client, two owned features, three production platforms.","layout":{"breakpoints":{"stackMax":650,"fullCoreMax":1080}},"eyebrow":"Contribution boundary","features":[{"key":"payments","name":"Razorpay payments","role":"End-to-end payment boundary","steps":["Backend order creation","Cross-platform Razorpay checkout","Signature verification + webhooks"]},{"key":"notifications","name":"Push notifications","role":"Automatic product journeys","steps":["Hasura event trigger","FCM / APNs delivery","Destination-aware deep-link routing"]}],"platforms":["Web","Android","iOS"],"sharedCore":{"name":"React + Capacitor","role":"One shared client application"},"description":"Web, Android, and iOS share one React and Capacitor client that branches into the two end-to-end feature boundaries owned during the engagement: Razorpay payments and event-driven notification journeys."},"schemaVersion":3}$case_study$::jsonb,
  3,
  'published'
)
on conflict (slug) do update set
  name = excluded.name,
  url = excluded.url,
  category = excluded.category,
  title = excluded.title,
  challenge = excluded.challenge,
  delivery = excluded.delivery,
  capabilities = excluded.capabilities,
  metrics = excluded.metrics,
  has_case_study = excluded.has_case_study,
  case_study_document = excluded.case_study_document,
  order_index = excluded.order_index,
  status = excluded.status;

update public.projects
set case_study_document = jsonb_set(
  case_study_document,
  '{role}',
  to_jsonb('Backend lead: Architecture, API design, integrations, infrastructure, production support, complete technical ownership.'::text),
  false
)
where slug = 'delivery-intelligence-the-sleep-company'
  and has_case_study = true
  and case_study_document is not null;

update public.projects
set case_study_document = jsonb_set(
  case_study_document,
  '{sections}',
  (
    select jsonb_agg(
      case
        when section ->> 'id' = 'feature-scope' then
          $feature_scope${"id":"feature-scope","tone":"muted","eyebrow":"Feature scope","title":"Two production features, delivered through one shared cross-platform client.","type":"evidence-grid","columns":3,"cards":[{"title":"Shared client foundation","detail":"One React and Capacitor application carried the common client contracts and platform configuration across web, Android, and iOS.","keywords":["React + Capacitor","web + native","one client"]},{"title":"Payments, end to end","detail":"Ownership ran from backend order creation and Razorpay checkout through signature verification and independent webhook reconciliation.","keywords":["order creation","checkout","verification"]},{"title":"Notifications, event to destination","detail":"Ownership ran from Hasura-triggered product events through FCM or APNs delivery and destination-aware navigation after a tap.","keywords":["Hasura events","FCM + APNs","deep linking"]}]}$feature_scope$::jsonb
        else section
      end
      order by ordinal
    )
    from jsonb_array_elements(case_study_document -> 'sections')
      with ordinality as case_sections(section, ordinal)
  ),
  false
)
where slug = 'horecah'
  and has_case_study = true
  and case_study_document is not null;
